function maxScore(nums) {
  nums.sort((a, b) => b - a);
  let prefix = 0;
  let score = 0;

  for (let i = 0; i < nums.length; i++) {
    prefix += nums[i];
    if (prefix <= 0) {
      break;
    }
    score++;
  }
  return score;
}

