function maxScore(nums) {
  let best = 0;
  const used = new Array(nums.length).fill(false);
  const place = (depth, total, positives) => {
    if (positives > best) best = positives;
    if (depth === nums.length) return;
    for (let j = 0; j < nums.length; j++) {
      if (used[j]) continue;
      used[j] = true;
      const next = total + nums[j];
      place(depth + 1, next, positives + (next > 0 ? 1 : 0));
      used[j] = false;
    }
  };
  place(0, 0, 0);
  return best;
}

