function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 7);
  const span = size === 'large' ? 1000000 : pick(1, 6);
  const mode = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    let v = pick(-span, span);
    if (mode < 0.15) v = Math.abs(v);
    else if (mode < 0.3) v = -Math.abs(v);
    else if (mode < 0.6 && v > 0 && rand() < 0.4) v = -v;
    nums.push(v);
  }
  return [nums];
}
